    static func encode(_ settings: UnyriSidebarAppearanceSettings) -> String {
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        guard let data = try? encoder.encode(settings.sanitized()), let raw = String(data: data, encoding: .utf8) else { return "{\"version\":1}" }
        return raw
    }
}

