    func metrics(screenWidth: CGFloat) -> Metrics {
        let viewport = screenWidth.isFinite && screenWidth > 0 ? screenWidth : 1
        let panel = viewport * geometryWidth / 100
        let inset = min(geometryInset, max(6, (panel - 120) / 2))
        let content = max(64, panel - 2 * inset)
        let padding = min(profilePadding, content / 10)
        let layout = content < 112 ? "center" : profileLayout
        let avatar = layout == "center" ? min(avatarSize, content - 2 * padding)
            : min(avatarSize, max(26, content - 2 * padding - (profileShowClose ? 44 : 0) - 2 * profileGap - 60))
        let rowPadding = min(geometryRowPaddingX, content / 6)
        let rowContent = content - 2 * rowPadding
        return Metrics(panelWidth: panel, inset: inset, contentWidth: content, profileLayout: layout,
            profilePadding: padding, avatarSize: avatar, rowPaddingX: rowPadding, rowContentWidth: rowContent,
            tilePadding: min(iconsTileSize, max(0, (rowContent - iconsSize) / 2)),
            iconGap: min(geometryIconGap, content / 8), editIndent: min(editIndent, content / 5),
            quickSideBySide: quickLayout == "row" && content >= 136 + quickGap)
